import React, { useEffect, useState, useRef } from 'react';
import { Card, CardHeader, Table, Btn, Badge, Modal, FormRow, FormField, SearchBar, Spinner } from '../components/ui/Card';
import api from '../utils/api';
import toast from 'react-hot-toast';
import { useAuth } from '../contexts/AuthContext';
import logo from '../assets/logo-lhm.png';

const SERVICES = ['Direction', 'Administration', 'Logistique', 'Communication', 'Mobilisation', 'Technique'];
const CONTRATS = ['CDI', 'CDD', 'Bénévole', 'Stage', 'Autre'];
const STATUTS_FAMILLE = ['Célibataire', 'Marié(e)', 'Divorcé(e)', 'Veuf/Veuve'];

const defaultForm = {
  nom: '', prenom: '', nom_jeune_fille: '', date_naissance: '', lieu_naissance: '',
  adresse: '', telephone: '', email: '', situation_familiale: 'Célibataire',
  contact_urgence_nom: '', contact_urgence_tel: '',
  poste: '', service: 'Administration', type_contrat: 'CDI', date_entree: '',
  superieur: '', cnaps: '', aro: '', statut: 'actif',
  photo: ''
};

// ──────────────────────────────────────────────────────────────
// COMPOSANT PHOTO UPLOAD
// ──────────────────────────────────────────────────────────────
function PhotoUpload({ value, onChange }) {
  const fileRef = useRef();
  const handleFile = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    if (file.size > 2 * 1024 * 1024) { toast.error('Photo trop lourde (max 2 Mo)'); return; }
    const reader = new FileReader();
    reader.onload = (ev) => onChange(ev.target.result);
    reader.readAsDataURL(file);
  };
  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 10 }}>
      <div
        onClick={() => fileRef.current.click()}
        style={{ width: 110, height: 120, borderRadius: 12, border: '2px dashed var(--gold)', background: value ? 'transparent' : 'var(--gray-50)', cursor: 'pointer', overflow: 'hidden', display: 'flex', alignItems: 'center', justifyContent: 'center', position: 'relative', transition: 'all 0.2s' }}
      >
        {value
          ? <img src={value} alt="Photo" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
          : <div style={{ textAlign: 'center', color: 'var(--gray-400)', fontSize: '0.75rem' }}>
              <div style={{ fontSize: '2rem', marginBottom: 4 }}>📷</div>
              <span>Cliquez pour<br/>choisir</span>
            </div>
        }
      </div>
      <input ref={fileRef} type="file" accept="image/*" onChange={handleFile} style={{ display: 'none' }} />
      <div style={{ display: 'flex', gap: 6 }}>
        <button type="button" onClick={() => fileRef.current.click()}
          style={{ fontSize: '0.72rem', padding: '4px 10px', border: '1px solid var(--gold)', borderRadius: 6, background: 'transparent', color: 'var(--gold-dark)', cursor: 'pointer', fontWeight: 600 }}>
          {value ? '🔄 Changer' : '📷 Ajouter'}
        </button>
        {value && <button type="button" onClick={() => onChange('')}
          style={{ fontSize: '0.72rem', padding: '4px 10px', border: '1px solid var(--gray-200)', borderRadius: 6, background: 'transparent', color: 'var(--gray-500)', cursor: 'pointer' }}>
          ✕ Supprimer
        </button>}
      </div>
    </div>
  );
}

// ──────────────────────────────────────────────────────────────
// IMPRESSION PDF / LISTE
// ──────────────────────────────────────────────────────────────
function printPersonnelList(data, filterService) {
  const now = new Date().toLocaleDateString('fr-FR', { year: 'numeric', month: 'long', day: 'numeric' });
  const html = `<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8"/>
<title>Liste du Personnel — LHM Madagascar</title>
<style>
  @page { size: A4 landscape; margin: 15mm 12mm; }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: Arial, sans-serif; font-size: 10px; color: #222; background: white; }
  .header { display: flex; align-items: center; gap: 16px; margin-bottom: 16px; padding-bottom: 12px; border-bottom: 3px solid #0f2044; }
  .header img { height: 52px; object-fit: contain; }
  .header-text h1 { font-size: 16px; color: #0f2044; font-weight: 700; }
  .header-text p { font-size: 10px; color: #666; margin-top: 2px; }
  .badge { display: inline-block; padding: 2px 7px; border-radius: 10px; font-size: 9px; font-weight: 600; }
  .badge-actif { background: #dcfce7; color: #166534; }
  .badge-inactif { background: #fee2e2; color: #991b1b; }
  table { width: 100%; border-collapse: collapse; margin-top: 8px; }
  thead tr { background: #0f2044; color: white; }
  thead th { padding: 7px 8px; text-align: left; font-size: 9px; font-weight: 600; letter-spacing: 0.03em; }
  tbody tr:nth-child(even) { background: #f8faff; }
  tbody tr:hover { background: #eff6ff; }
  td { padding: 6px 8px; border-bottom: 1px solid #e5e7eb; vertical-align: middle; }
  .photo-cell { width: 36px; text-align: center; }
  .photo-cell img { width: 30px; height: 34px; object-fit: cover; border-radius: 4px; border: 1px solid #ddd; }
  .no-photo { width: 30px; height: 34px; background: #e5e7eb; border-radius: 4px; display: inline-flex; align-items: center; justify-content: center; font-size: 13px; }
  .matricule { font-family: monospace; font-weight: 700; color: #0f2044; }
  .nom { font-weight: 600; color: #0f2044; }
  .sub { font-size: 9px; color: #6b7280; }
  .footer { margin-top: 14px; text-align: center; font-size: 9px; color: #9ca3af; border-top: 1px solid #e5e7eb; padding-top: 8px; }
  .gold { color: #c9a84c; font-weight: 700; }
  .stat-row { display: flex; gap: 20px; margin-bottom: 12px; }
  .stat { background: #f0f4ff; border: 1px solid #dbeafe; border-radius: 8px; padding: 8px 14px; }
  .stat-num { font-size: 18px; font-weight: 700; color: #0f2044; }
  .stat-label { font-size: 9px; color: #6b7280; }
</style>
</head>
<body>
<div class="header">
  <img src="${window.location.origin}/logo-lhm.png" onerror="this.style.display='none'" alt="LHM" />
  <div class="header-text">
    <h1>Liste du Personnel — LHM Madagascar</h1>
    <p>Feon'ny Filazantsara &nbsp;|&nbsp; ${filterService ? 'Service : ' + filterService : 'Tous les services'} &nbsp;|&nbsp; Imprimé le ${now}</p>
  </div>
</div>
<div class="stat-row">
  <div class="stat"><div class="stat-num">${data.length}</div><div class="stat-label">Total affiché</div></div>
  <div class="stat"><div class="stat-num">${data.filter(p=>p.statut==='actif').length}</div><div class="stat-label">Actifs</div></div>
  <div class="stat"><div class="stat-num">${[...new Set(data.map(p=>p.service))].length}</div><div class="stat-label">Services</div></div>
</div>
<table>
  <thead>
    <tr>
      <th>Photo</th>
      <th>Matricule</th>
      <th>Nom & Prénom</th>
      <th>Téléphone</th>
      <th>Poste</th>
      <th>Service</th>
      <th>Contrat</th>
      <th>Date Entrée</th>
      <th>N° CNAPS</th>
      <th>Statut</th>
    </tr>
  </thead>
  <tbody>
    ${data.map(p => `
    <tr>
      <td class="photo-cell">${p.photo ? `<img src="${p.photo}" alt="photo" />` : '<div class="no-photo">👤</div>'}</td>
      <td class="matricule">${p.matricule || '—'}</td>
      <td>
        <div class="nom">${p.prenom || ''} ${p.nom || ''}</div>
        <div class="sub">${p.email || ''}</div>
      </td>
      <td>${p.telephone || '—'}</td>
      <td>${p.poste || '—'}</td>
      <td>${p.service || '—'}</td>
      <td>${p.type_contrat || '—'}</td>
      <td>${p.date_entree ? new Date(p.date_entree).toLocaleDateString('fr-FR') : '—'}</td>
      <td>${p.cnaps || '—'}</td>
      <td><span class="badge badge-${p.statut}">${p.statut}</span></td>
    </tr>`).join('')}
  </tbody>
</table>
<div class="footer">
  LHM Madagascar — Feon'ny Filazantsara &nbsp;•&nbsp; Document confidentiel — Usage interne &nbsp;•&nbsp; ${data.length} membre(s)
</div>
</body>
</html>`;

  const w = window.open('', '_blank', 'width=1100,height=750');
  w.document.write(html);
  w.document.close();
  w.onload = () => { w.print(); };
}

function printPersonnelFiche(p) {
  const now = new Date().toLocaleDateString('fr-FR', { year: 'numeric', month: 'long', day: 'numeric' });
  const html = `<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8"/>
<title>Fiche Personnel — ${p.prenom} ${p.nom}</title>
<style>
  @page { size: A4 portrait; margin: 15mm; }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: Arial, sans-serif; font-size: 11px; color: #222; }
  .header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 20px; padding-bottom: 14px; border-bottom: 3px solid #0f2044; }
  .header img.org-logo { height: 48px; }
  .header-center h1 { font-size: 18px; color: #0f2044; font-weight: 700; text-align: center; }
  .header-center p { font-size: 10px; color: #999; text-align: center; margin-top: 2px; }
  .photo-box { width: 80px; height: 96px; border: 2px solid #c9a84c; border-radius: 8px; overflow: hidden; display: flex; align-items: center; justify-content: center; background: #f5f5f5; }
  .photo-box img { width: 100%; height: 100%; object-fit: cover; }
  .identity { display: flex; gap: 20px; background: linear-gradient(135deg, #0f2044, #1a3a6e); color: white; padding: 16px 20px; border-radius: 10px; margin-bottom: 18px; align-items: center; }
  .identity-text h2 { font-size: 18px; font-weight: 700; }
  .identity-text p { font-size: 11px; opacity: 0.8; margin-top: 4px; }
  .identity-text .mat { font-family: monospace; background: rgba(201,168,76,0.3); padding: 2px 8px; border-radius: 4px; font-size: 12px; color: #c9a84c; font-weight: 700; display: inline-block; margin-top: 6px; }
  .section { margin-bottom: 16px; }
  .section-title { font-size: 10px; font-weight: 700; color: #c9a84c; text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 10px; border-bottom: 1px solid #e5e7eb; padding-bottom: 4px; }
  .grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px 20px; }
  .field label { font-size: 9px; color: #9ca3af; text-transform: uppercase; letter-spacing: 0.05em; display: block; margin-bottom: 2px; }
  .field span { font-size: 11px; color: #0f2044; font-weight: 500; }
  .footer { margin-top: 20px; text-align: center; font-size: 9px; color: #9ca3af; border-top: 1px solid #e5e7eb; padding-top: 8px; }
</style>
</head>
<body>
<div class="header">
  <img class="org-logo" src="${window.location.origin}/logo-lhm.png" onerror="this.style.display='none'" alt="LHM" />
  <div class="header-center">
    <h1>Fiche du Personnel</h1>
    <p>Document confidentiel — Imprimé le ${now}</p>
  </div>
  <div style="width:80px"></div>
</div>

<div class="identity">
  <div class="photo-box">
    ${p.photo ? `<img src="${p.photo}" alt="photo" />` : '<div style="font-size:2.5rem;color:#ccc">👤</div>'}
  </div>
  <div class="identity-text">
    <h2>${p.prenom} ${p.nom}${p.nom_jeune_fille ? ` (née ${p.nom_jeune_fille})` : ''}</h2>
    <p>${p.poste || ''} — ${p.service || ''}</p>
    <p>${p.email || ''} &nbsp;|&nbsp; ${p.telephone || ''}</p>
    <div class="mat">${p.matricule || '—'}</div>
  </div>
</div>

<div class="section">
  <div class="section-title">A — Informations personnelles</div>
  <div class="grid">
    <div class="field"><label>Date de naissance</label><span>${p.date_naissance ? new Date(p.date_naissance).toLocaleDateString('fr-FR') : '—'}</span></div>
    <div class="field"><label>Lieu de naissance</label><span>${p.lieu_naissance || '—'}</span></div>
    <div class="field"><label>Situation familiale</label><span>${p.situation_familiale || '—'}</span></div>
    <div class="field"><label>Adresse</label><span>${p.adresse || '—'}</span></div>
    <div class="field"><label>Contact urgence</label><span>${p.contact_urgence_nom || '—'}</span></div>
    <div class="field"><label>Tél. urgence</label><span>${p.contact_urgence_tel || '—'}</span></div>
  </div>
</div>

<div class="section">
  <div class="section-title">B — Informations professionnelles</div>
  <div class="grid">
    <div class="field"><label>Poste</label><span>${p.poste || '—'}</span></div>
    <div class="field"><label>Service</label><span>${p.service || '—'}</span></div>
    <div class="field"><label>Type de contrat</label><span>${p.type_contrat || '—'}</span></div>
    <div class="field"><label>Date d'entrée</label><span>${p.date_entree ? new Date(p.date_entree).toLocaleDateString('fr-FR') : '—'}</span></div>
    <div class="field"><label>Statut</label><span>${p.statut || '—'}</span></div>
  </div>
</div>

<div class="section">
  <div class="section-title">D — Administratif</div>
  <div class="grid">
    <div class="field"><label>N° CNAPS</label><span>${p.cnaps || '—'}</span></div>
    <div class="field"><label>N° ARO</label><span>${p.aro || '—'}</span></div>
  </div>
</div>

<div class="footer">
  LHM Madagascar — Feon'ny Filazantsara &nbsp;•&nbsp; Fiche confidentielle — Usage interne uniquement
</div>
</body>
</html>`;

  const w = window.open('', '_blank', 'width=820,height=1000');
  w.document.write(html);
  w.document.close();
  w.onload = () => { w.print(); };
}

// ──────────────────────────────────────────────────────────────
// PAGE PRINCIPALE
// ──────────────────────────────────────────────────────────────
export default function PersonnelPage() {
  const { hasRole } = useAuth();
  const [personnel, setPersonnel] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [filterService, setFilterService] = useState('');
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState(defaultForm);
  const [saving, setSaving] = useState(false);

  const canEdit = hasRole('super_admin', 'assistant_admin');

  useEffect(() => {
    document.getElementById('page-title') && (document.getElementById('page-title').textContent = 'Gestion du Personnel');
    loadPersonnel();
  }, []);

  const loadPersonnel = async () => {
    setLoading(true);
    try {
      const r = await api.get('/personnel');
      setPersonnel(r.data.data);
    } catch { toast.error('Erreur de chargement'); }
    finally { setLoading(false); }
  };

  const filtered = personnel.filter(p => {
    const s = search.toLowerCase();
    const matchSearch = !s || p.nom?.toLowerCase().includes(s) || p.prenom?.toLowerCase().includes(s) || p.matricule?.toLowerCase().includes(s) || p.poste?.toLowerCase().includes(s);
    const matchService = !filterService || p.service === filterService;
    return matchSearch && matchService;
  });

  const openModal = (p = null) => {
    setEditing(p);
    setForm(p ? { ...defaultForm, ...p } : defaultForm);
    setModalOpen(true);
  };

  const handleSave = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      if (editing) {
        await api.put(`/personnel/${editing.id}`, form);
        toast.success('Personnel mis à jour');
      } else {
        await api.post('/personnel', form);
        toast.success('Personnel créé');
      }
      setModalOpen(false);
      loadPersonnel();
    } catch (err) {
      toast.error(err.response?.data?.message || 'Erreur');
    } finally { setSaving(false); }
  };

  const handleDeactivate = async (id) => {
    if (!window.confirm('Désactiver ce membre du personnel ?')) return;
    try {
      await api.delete(`/personnel/${id}`);
      toast.success('Personnel désactivé');
      loadPersonnel();
    } catch { toast.error('Erreur'); }
  };

  const columns = [
    { key: 'photo', header: 'Photo', render: (v, row) => (
      <div style={{ width: 38, height: 44, borderRadius: 8, overflow: 'hidden', border: '1.5px solid var(--gray-200)', background: 'var(--gray-100)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        {v ? <img src={v} alt={row.prenom} style={{ width: '100%', height: '100%', objectFit: 'cover' }} /> : <span style={{ fontSize: '1.2rem' }}>👤</span>}
      </div>
    )},
    { key: 'matricule', header: 'Matricule', render: v => <span style={{ fontFamily: 'monospace', fontWeight: 700, color: 'var(--navy)', fontSize: '0.82rem' }}>{v}</span> },
    { key: 'nom', header: 'Nom & Prénom', render: (_, row) => (
      <div>
        <p style={{ fontWeight: 600, color: 'var(--navy)' }}>{row.prenom} {row.nom}</p>
        <p style={{ fontSize: '0.73rem', color: 'var(--gray-400)' }}>{row.email}</p>
      </div>
    )},
    { key: 'poste', header: 'Poste' },
    { key: 'service', header: 'Service', render: v => <Badge type="info">{v}</Badge> },
    { key: 'type_contrat', header: 'Contrat', render: v => <Badge type="gold">{v}</Badge> },
    { key: 'statut', header: 'Statut', render: v => <Badge type={v === 'actif' ? 'success' : 'error'}>{v}</Badge> },
    { key: 'actions', header: 'Actions', render: (_, row) => (
      <div style={{ display: 'flex', gap: 5, flexWrap: 'wrap' }}>
        <Btn size="sm" variant="secondary" onClick={() => printPersonnelFiche(row)} title="Imprimer la fiche">🖨️</Btn>
        <Btn size="sm" variant="secondary" onClick={() => openModal(row)}>✏️</Btn>
        {canEdit && <Btn size="sm" variant="danger" onClick={() => handleDeactivate(row.id)}>🗑️</Btn>}
      </div>
    )}
  ];

  return (
    <div className="animate-fade">
      <Card style={{ marginBottom: 20 }}>
        <CardHeader
          title="Gestion du Personnel"
          subtitle={`${filtered.length} membre(s) trouvé(s)`}
          action={
            <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
              <Btn variant="secondary" onClick={() => printPersonnelList(filtered, filterService)}>
                🖨️ Imprimer la liste
              </Btn>
              {canEdit && <Btn variant="gold" onClick={() => openModal()}>➕ Nouveau membre</Btn>}
            </div>
          }
        />
        <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
          <div style={{ flex: 1, minWidth: 180 }}>
            <SearchBar value={search} onChange={setSearch} placeholder="Rechercher par nom, poste..." />
          </div>
          <select value={filterService} onChange={e => setFilterService(e.target.value)} style={{ width: 'auto', minWidth: 150 }}>
            <option value="">Tous les services</option>
            {SERVICES.map(s => <option key={s} value={s}>{s}</option>)}
          </select>
        </div>
      </Card>

      <Card>
        {loading ? <Spinner /> : <Table columns={columns} data={filtered} emptyMessage="Aucun personnel enregistré" />}
      </Card>

      {/* MODAL FORMULAIRE */}
      <Modal open={modalOpen} onClose={() => setModalOpen(false)} title={editing ? `Modifier — ${editing.prenom} ${editing.nom}` : 'Nouveau membre du personnel'} width={720}>
        <form onSubmit={handleSave} style={{ padding: '24px' }}>

          {/* PHOTO EN HAUT */}
          <div style={{ display: 'flex', gap: 24, marginBottom: 24, paddingBottom: 20, borderBottom: '1px solid var(--gray-100)', flexWrap: 'wrap' }}>
            <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 8, minWidth: 130 }}>
              <p style={{ fontSize: '0.72rem', fontWeight: 700, color: 'var(--gold-dark)', textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: 4 }}>Photo</p>
              <PhotoUpload value={form.photo} onChange={v => setForm({...form, photo: v})} />
            </div>
            <div style={{ flex: 1, minWidth: 200 }}>
              <p style={{ fontSize: '0.72rem', fontWeight: 700, color: 'var(--gold-dark)', textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: 10 }}>Identification rapide</p>
              <FormRow>
                <FormField label="Prénom *"><input value={form.prenom} onChange={e => setForm({...form, prenom: e.target.value})} required /></FormField>
                <FormField label="Nom *"><input value={form.nom} onChange={e => setForm({...form, nom: e.target.value})} required /></FormField>
              </FormRow>
              <FormRow>
                <FormField label="Poste *"><input value={form.poste} onChange={e => setForm({...form, poste: e.target.value})} required /></FormField>
                <FormField label="Service">
                  <select value={form.service} onChange={e => setForm({...form, service: e.target.value})}>
                    {SERVICES.map(s => <option key={s}>{s}</option>)}
                  </select>
                </FormField>
              </FormRow>
            </div>
          </div>

          {/* Section A */}
          <div style={{ marginBottom: 20, paddingBottom: 16, borderBottom: '1px solid var(--gray-100)' }}>
            <h4 style={{ color: 'var(--gold-dark)', fontWeight: 700, fontSize: '0.75rem', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: 14 }}>A — Informations personnelles</h4>
            <FormRow>
              <FormField label="Date de naissance"><input type="date" value={form.date_naissance} onChange={e => setForm({...form, date_naissance: e.target.value})} /></FormField>
              <FormField label="Lieu de naissance"><input value={form.lieu_naissance} onChange={e => setForm({...form, lieu_naissance: e.target.value})} /></FormField>
            </FormRow>
            <FormRow cols={1}>
              <FormField label="Adresse"><input value={form.adresse} onChange={e => setForm({...form, adresse: e.target.value})} /></FormField>
            </FormRow>
            <FormRow>
              <FormField label="Téléphone"><input value={form.telephone} onChange={e => setForm({...form, telephone: e.target.value})} /></FormField>
              <FormField label="Email"><input type="email" value={form.email} onChange={e => setForm({...form, email: e.target.value})} /></FormField>
            </FormRow>
            <FormRow>
              <FormField label="Situation familiale">
                <select value={form.situation_familiale} onChange={e => setForm({...form, situation_familiale: e.target.value})}>
                  {STATUTS_FAMILLE.map(s => <option key={s}>{s}</option>)}
                </select>
              </FormField>
              <FormField label="Nom de jeune fille"><input value={form.nom_jeune_fille} onChange={e => setForm({...form, nom_jeune_fille: e.target.value})} /></FormField>
            </FormRow>
            <FormRow>
              <FormField label="Contact urgence — Nom"><input value={form.contact_urgence_nom} onChange={e => setForm({...form, contact_urgence_nom: e.target.value})} /></FormField>
              <FormField label="Contact urgence — Tél."><input value={form.contact_urgence_tel} onChange={e => setForm({...form, contact_urgence_tel: e.target.value})} /></FormField>
            </FormRow>
          </div>

          {/* Section B */}
          <div style={{ marginBottom: 20, paddingBottom: 16, borderBottom: '1px solid var(--gray-100)' }}>
            <h4 style={{ color: 'var(--gold-dark)', fontWeight: 700, fontSize: '0.75rem', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: 14 }}>B — Informations professionnelles</h4>
            <FormRow>
              <FormField label="Type de contrat">
                <select value={form.type_contrat} onChange={e => setForm({...form, type_contrat: e.target.value})}>
                  {CONTRATS.map(c => <option key={c}>{c}</option>)}
                </select>
              </FormField>
              <FormField label="Date d'entrée"><input type="date" value={form.date_entree} onChange={e => setForm({...form, date_entree: e.target.value})} /></FormField>
            </FormRow>
            <FormRow>
              <FormField label="Statut">
                <select value={form.statut} onChange={e => setForm({...form, statut: e.target.value})}>
                  <option value="actif">Actif</option>
                  <option value="inactif">Inactif</option>
                  <option value="suspendu">Suspendu</option>
                </select>
              </FormField>
              <div />
            </FormRow>
          </div>

          {/* Section D */}
          <div>
            <h4 style={{ color: 'var(--gold-dark)', fontWeight: 700, fontSize: '0.75rem', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: 14 }}>D — Administratif</h4>
            <FormRow>
              <FormField label="N° CNAPS"><input value={form.cnaps} onChange={e => setForm({...form, cnaps: e.target.value})} /></FormField>
              <FormField label="N° ARO"><input value={form.aro} onChange={e => setForm({...form, aro: e.target.value})} /></FormField>
            </FormRow>
          </div>

          <div style={{ display: 'flex', gap: 10, justifyContent: 'flex-end', paddingTop: 20, borderTop: '1px solid var(--gray-100)', marginTop: 8, flexWrap: 'wrap' }}>
            <Btn type="button" variant="secondary" onClick={() => setModalOpen(false)}>Annuler</Btn>
            {editing && <Btn type="button" variant="secondary" onClick={() => printPersonnelFiche({ ...form, matricule: editing.matricule })}>🖨️ Imprimer</Btn>}
            <Btn type="submit" variant="gold" disabled={saving}>{saving ? 'Enregistrement...' : editing ? '💾 Mettre à jour' : '➕ Créer'}</Btn>
          </div>
        </form>
      </Modal>
    </div>
  );
}
